package com.bank.sensitive;

import java.util.logging.*;

public class SensitiveDataDemo {
    private static final Logger log = Logger.getLogger(SensitiveDataDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CredentialStore store = new CredentialStore();
        SensitiveLogger safeLog = new SensitiveLogger();

        // Password stored as a one-way hash — a leak reveals nothing usable.
        String hash = store.storePassword("rajesh", "Str0ng!Passphrase");
        log.info(() -> "Stored password as hash (not recoverable): " + hash);
        log.info(() -> "Verify correct password: " + store.verify("rajesh", "Str0ng!Passphrase"));

        // Logs MASK account and card numbers — no PII leak.
        safeLog.logTransfer("1234567890122001", "4111111111111111", 50000);

        // Transport is TLS-only.
        log.info(() -> "Transport policy: " + TlsPolicy.describe());
    }
}

