class CredentialStore {
    private final java.util.Map<String, String> hashes = new java.util.HashMap<>();

    // Simulated bcrypt: in production use BCryptPasswordEncoder(12).
    String storePassword(String username, String rawPassword) {
        String hash = "bcrypt$12$" + Integer.toHexString(("salt" + rawPassword).hashCode());
        hashes.put(username, hash);
        return hash;
    }
    boolean verify(String username, String rawPassword) {
        String expected = "bcrypt$12$" + Integer.toHexString(("salt" + rawPassword).hashCode());
        return expected.equals(hashes.get(username));
    }
}

