class SensitiveLogger {
    private static final Logger log = Logger.getLogger(SensitiveLogger.class.getName());

    void logTransfer(String accountNumber, String cardNumber, long amount) {
        // Log only masked values — last 4 digits visible, rest hidden.
        log.info("Transfer amount=" + amount
            + " account=" + mask(accountNumber) + " card=" + mask(cardNumber));
    }
    private String mask(String value) {
        if (value == null || value.length() <= 4) return "****";
        return "****" + value.substring(value.length() - 4);
    }
}

// ─── Would be in TlsPolicy.java ───
class TlsPolicy {
    static String describe() {
        return "HTTPS only, HSTS enabled, strong ciphers, HTTP->HTTPS redirect";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
